import fs from "node:fs";
import OpenAI from "openai";

const openai = new OpenAI();

export interface Turn {
  speaker: string;
  start: number;
  end: number;
  text: string;
}

export async function turns(path: string): Promise<Turn[]> {
  const transcript = await openai.audio.transcriptions.create({
    model: "gpt-4o-transcribe-diarize",
    file: fs.createReadStream(path),
    response_format: "diarized_json",
    chunking_strategy: "auto",
  });
  return transcript.segments.map((s) => ({ speaker: s.speaker, start: s.start, end: s.end, text: s.text }));
}

package main

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"os"
)

func speak(text string) ([]byte, error) {
	body, _ := json.Marshal(map[string]string{"model": "tts-1", "voice": "alloy", "input": text})
	req, _ := http.NewRequest("POST", "https://api.openai.com/v1/audio/speech", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer "+os.Getenv("OPENAI_API_KEY"))
	req.Header.Set("Content-Type", "application/json")
	res, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer res.Body.Close()
	return io.ReadAll(res.Body)
}

from openai import OpenAI

client = OpenAI()


def speak(text: str) -> bytes:
    return client.audio.speech.create(model="tts-1-hd", voice="nova", input=text).content


def speak_briskly(text: str) -> bytes:
    return client.audio.speech.create(model="tts-1", voice="nova", input=text, speed=1.1).content


def speak_fast(text: str) -> bytes:
    return client.audio.speech.create(model="tts-1", voice="nova", input=text, speed=2.0).content


def speak_lossless(text: str) -> bytes:
    return client.audio.speech.create(model="tts-1-hd", voice="nova", input=text, response_format="flac").content


def to_english(path: str) -> str:
    with open(path, "rb") as audio_file:
        return client.audio.translations.create(model="whisper-1", file=audio_file).text

