export async function POST(request: Request) {
  const { text } = await request.json();
  const response = await fetch("https://api.openai.com/v1/audio/speech", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ model: "gpt-4o-mini-tts", voice: "sage", input: text }),
  });
  if (!response.ok) {
    return Response.json({ error: "Speech failed" }, { status: 502 });
  }
  return new Response(response.body, { headers: { "Content-Type": "audio/mpeg" } });
}

import openai
from fastapi import FastAPI, HTTPException
from fastapi.responses import StreamingResponse
from openai import OpenAI

app = FastAPI()
client = OpenAI(max_retries=4)


@app.get("/speak")
def speak(text: str):
    try:
        response = client.audio.speech.create(model="tts-1", voice="alloy", input=text)
    except openai.RateLimitError:
        raise HTTPException(status_code=429, detail="Busy, try again")
    except openai.APIError:
        raise HTTPException(status_code=502, detail="Speech failed")
    return StreamingResponse(response.iter_bytes(), media_type="audio/mpeg")

