import express from "express";
import OpenAI from "openai";

const app = express();
const openai = new OpenAI();

// The browser app (served from another repo) calls this for a Realtime credential.
app.get("/api/token", async (_req, res) => {
  const r = await fetch("https://api.openai.com/v1/realtime/client_secrets", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      session: {
        type: "realtime",
        model: "gpt-realtime",
        instructions: "You are a cheerful concierge.",
        audio: { output: { voice: "marin" } },
      },
    }),
  });
  const data = await r.json();
  res.json({ value: data.value });
});

app.get("/api/welcome", async (_req, res) => {
  const speech = await openai.audio.speech.create({ model: "tts-1", voice: "alloy", input: "Welcome back!" });
  res.type("audio/mpeg").send(Buffer.from(await speech.arrayBuffer()));
});

app.listen(3000);
